package com.example.starter;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * 航班除冰时隙业务工程入口；本地启动使用 H2 内存库（MODE=MySQL），自动建表并初始化合成数据。
 */
@SpringBootApplication
public class StarterApplication {

    /**
     * 使用内置 H2 内存库配置启动服务，进程退出后数据不保留。
     */
    public static void main(String[] args) {
        SpringApplication.run(StarterApplication.class, args);
    }
}
'@
[System.IO.File]::WriteAllText("$PWD\src\main\java\com\example\starter\StarterApplication.java", $app, $enc)

$yaml = @'
spring:
  application:
    name: gitcangku1
  datasource:
    url: jdbc:h2:mem:deicing;MODE=MySQL;DB_CLOSE_DELAY=-1
    username: sa
    password: ""
    driver-class-name: org.h2.Driver
    hikari:
      maximum-pool-size: 5
      minimum-idle: 1
      connection-timeout: 10000
      validation-timeout: 3000
  sql:
    init:
      mode: always
      encoding: UTF-8
  jackson:
    time-zone: UTC
  lifecycle:
    timeout-per-shutdown-phase: 20s

server:
  port: 8080
  shutdown: graceful
  error:
    include-message: never
    include-stacktrace: never

management:
  endpoints:
    web:
      exposure:
        include: health
  endpoint:
    health:
      show-details: never
'@
[System.IO.File]::WriteAllText("$PWD\src\main\resources\application.yaml", $yaml, $enc)
Write-Output "done""}

