 * @param endUtc 时隙结束（UTC，不含），左闭右开
 * @param status 时隙状态
 */
public record DeicingSlot(
        Long id,
        String requestId,
        long vehicleId,
        long flightId,
        Instant startUtc,
        Instant endUtc,
        SlotStatus status) {
}
