    void clean() {
        jdbc.update("DELETE FROM takeoff_rejection");
        jdbc.update("DELETE FROM takeoff_clearance");
        jdbc.update("DELETE FROM deicing_completion");
        jdbc.update("DELETE FROM deicing_slot");
        clock.set(T0950);
    }

