 * 起飞拒绝历史记录器：独立事务写入，确认失败回滚时历史仍保留。
 */
@Service
public class RejectionRecorder {

    private final RejectionRepository rejectionRepository;

    public RejectionRecorder(RejectionRepository rejectionRepository) {
